def solve(T):
    n=len(T); m=n+1
    S=[lambda r,c:(c,r), lambda r,c:(m-r,m-c), lambda r,c:(m-c,m-r)]
    out=[row[:] for row in T]
    for r in range(n):
        for c in range(n):
            if T[r][c]==6:
                vals=[]
                for f in S:
                    rr,cc=f(r,c)
                    if 0<=rr<n and 0<=cc<n and T[rr][cc]!=6 and T[rr][cc] not in vals:
                        vals.append(T[rr][cc])
                if len(vals)==1: out[r][c]=vals[0]
    return out
